widget_scaffolding.data_template:
// src/core/{Name}Data.h
#pragma once
#include <string>
#include <vector>
#include <ctime>

struct {Name}Data {
    // --- domain fields ---
    bool valid = false;       // set true once first fetch succeeds
    time_t lastUpdate = 0;    // unix timestamp of last successful fetch
};

widget_scaffolding.provider_template:
// src/services/{Name}Provider.h
#pragma once
#include "core/{Name}Data.h"

class {Name}Provider {
public:
    static {Name}Provider& instance();
    void update();               // called on interval by main loop
    const {Name}Data& data() const { return _data; }
private:
    {Name}Provider() = default;
    {Name}Data _data;
    time_t _nextFetch = 0;
    static constexpr int FETCH_INTERVAL_S = 300;
};

widget_scaffolding.panel_template:
// src/ui/{Name}Panel.cpp
#include "{Name}Panel.h"
#include "../core/Theme.h"

void {Name}Panel::render(SDL_Renderer* renderer) {
    ThemeColors themes = getThemeColors(theme_);

    // Draw background
    SDL_SetRenderDrawColor(renderer, themes.bg.r, themes.bg.g, themes.bg.b, themes.bg.a);
    SDL_Rect r = {x_, y_, width_, height_};
    SDL_RenderFillRect(renderer, &r);

